// Check whether the most-recent file uploaded within the last 30 hours.
// (Backup runs Sun 2AM; this workflow runs Mon 6AM = ~28h window.)
const data = $input.first().json;
const files = data.files || [];
const nowMs = Date.now();
const freshest = files[0]; // B2 returns most-recent first by default
const freshTimestampMs = freshest ? freshest.uploadTimestamp : 0;
const ageHours = freshest ? (nowMs - freshTimestampMs) / 3600000 : null;
const ok = ageHours !== null && ageHours <= 30;
const msg = ok
  ? `B2 backup OK. Last file '${freshest.fileName}' uploaded ${ageHours.toFixed(1)}h ago.`
  : (files.length === 0
      ? 'B2 backup FAIL: bucket is EMPTY. Hyper Backup never ran or failed silently.'
      : `B2 backup STALE: last file is ${ageHours.toFixed(1)}h old (expected <30h). Check Hyper Backup job in DSM.`);
return [{ json: { ok, msg, ageHours, fileCount: files.length } }];
